// --- shared parser ---
/**
 * Article extraction shared by the n8n Source Ingest workflow and the dry-run
 * script. Pure functions with no n8n dependency so they can be tested directly
 * and pasted into a Code node.
 *
 * Two paths:
 *   parseFeed(xml)      — RSS 2.0, Atom and RDF, which is what the 37 feed
 *                         sources between them emit
 *   parseIndex(html,..) — heuristic article discovery for the sources with no
 *                         feed, scored rather than driven by per-site selectors
 *                         because 31 hand-written selector sets would rot faster
 *                         than they could be maintained
 */


// ─── Feeds ───────────────────────────────────────────────────────────────────

const strip = s =>
  (s ?? '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&(#\d+|#x[0-9a-f]+|\w+);/gi, ent => {
      const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };
      const key = ent.slice(1, -1);
      if (named[key]) return named[key];
      if (key[0] === '#') {
        const code = key[1] === 'x' ? parseInt(key.slice(2), 16) : parseInt(key.slice(1), 10);
        return Number.isFinite(code) ? String.fromCodePoint(code) : ' ';
      }
      return ' ';
    })
    .replace(/\s+/g, ' ')
    .trim();

const tag = (block, name) => {
  const m = block.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i'));
  return m ? strip(m[1]) : null;
};

/** Atom puts the URL in an attribute, RSS in element text. */
function entryLink(block) {
  const alt = block.match(/<link[^>]+rel=["']alternate["'][^>]*href=["']([^"']+)["']/i);
  if (alt) return alt[1];
  const href = block.match(/<link[^>]+href=["']([^"']+)["']/i);
  if (href) return href[1];
  const text = tag(block, 'link');
  if (text) return text;
  // Some feeds only carry a permalink guid.
  const guid = block.match(/<guid[^>]*>([\s\S]*?)<\/guid>/i);
  if (guid && /^https?:\/\//.test(strip(guid[1]))) return strip(guid[1]);
  return null;
}

function parseDate(raw) {
  if (!raw) return null;
  const t = Date.parse(raw);
  return Number.isFinite(t) ? new Date(t).toISOString() : null;
}

function parseFeed(xml, baseUrl) {
  const blocks = [...xml.matchAll(/<(item|entry)(?:\s[^>]*)?>([\s\S]*?)<\/\1>/gi)];
  const out = [];
  for (const [, , block] of blocks) {
    const link = entryLink(block);
    const title = tag(block, 'title');
    if (!link || !title) continue;
    out.push({
      url: absolute(link, baseUrl),
      title,
      author: tag(block, 'dc:creator') ?? tag(block, 'author') ?? null,
      published_at:
        parseDate(tag(block, 'pubDate')) ??
        parseDate(tag(block, 'published')) ??
        parseDate(tag(block, 'updated')) ??
        parseDate(tag(block, 'dc:date')),
      summary_raw:
        tag(block, 'description') ?? tag(block, 'summary') ?? tag(block, 'content') ?? null,
    });
  }
  return out;
}

// ─── HTML indexes ────────────────────────────────────────────────────────────

function absolute(href, base) {
  try {
    return new URL(href, base).href;
  } catch {
    return href;
  }
}

// Paths that are navigation, not articles.
const CHROME = /\/(tag|tags|category|categories|author|page|search|login|subscribe|contact|about|privacy|terms|sitemap|feed|rss|wp-|cdn-cgi)\b/i;
const ASSET = /\.(pdf|jpe?g|png|gif|svg|zip|docx?|xlsx?|pptx?|mp4|mp3)(\?|$)/i;

/**
 * Article links on a news index share a URL shape — most sites put a date or a
 * long slug in the path. Scoring on those signals finds articles across sites
 * that share no markup, which is the whole point: 31 sources, no two the same.
 */
function scoreLink(url, text, origin) {
  let score = 0;
  let path;
  try {
    const u = new URL(url);
    if (u.origin !== origin) return -1; // off-site
    path = u.pathname;
  } catch {
    return -1;
  }
  if (CHROME.test(path) || ASSET.test(path)) return -1;
  if (path === '/' || path.length < 12) return -1;

  if (/\/\d{4}\/\d{1,2}\//.test(path)) score += 4; // /2026/07/
  if (/\/\d{4}-\d{2}-\d{2}/.test(path)) score += 4;
  if (/-.*-.*-/.test(path)) score += 3; // multi-word slug
  score += Math.min(path.split('/').filter(Boolean).length, 4);

  const words = text.trim().split(/\s+/).length;
  if (words >= 4) score += 3;
  if (words >= 7) score += 2;
  if (words > 40) score -= 4; // whole paragraph scraped as link text
  if (text.trim().length < 15) score -= 3;

  return score;
}

/**
 * Some sites render the bare URL as the anchor text (AIDC does this for every
 * media release). Rebuilding a headline from the slug beats discarding the link.
 */
function titleFromSlug(url) {
  try {
    const last = new URL(url).pathname.replace(/\/+$/, '').split('/').pop() ?? '';
    const words = decodeURIComponent(last)
      .replace(/\.\w{2,5}$/, '')
      .replace(/[-_]+/g, ' ')
      .trim();
    if (words.split(/\s+/).length < 3) return null;
    return words.charAt(0).toUpperCase() + words.slice(1);
  } catch {
    return null;
  }
}

function parseIndex(html, pageUrl, { minScore = 6, limit = 40 } = {}) {
  const origin = new URL(pageUrl).origin;
  const seen = new Map();

  for (const m of html.matchAll(/<a\b[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const url = absolute(m[1], pageUrl);
    let title = strip(m[2]);
    // Anchor text that is just the href carries no information — the slug does.
    if (!title || /^https?:\/\//i.test(title) || title.length < 12) {
      title = titleFromSlug(url) ?? title;
    }
    if (!title) continue;
    const score = scoreLink(url, title, origin);
    if (score < minScore) continue;
    // Same URL can appear as image link and headline link; keep the better title.
    const prev = seen.get(url);
    if (!prev || title.length > prev.title.length) {
      seen.set(url, { url, title, author: null, published_at: null, summary_raw: null, _score: score });
    }
  }

  return [...seen.values()]
    .sort((a, b) => b._score - a._score)
    .slice(0, limit)
    .map(({ _score, ...rest }) => rest);
}

// ─── Normalisation ───────────────────────────────────────────────────────────

/**
 * Hash of the normalised title plus the opening of the body. The same story is
 * syndicated across AEMO, RenewEconomy and the trade press under different URLs,
 * so URL identity alone will not deduplicate the sheet.
 */
function contentHash(article) {
  const basis = [
    (article.title ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(),
    (article.summary_raw ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 300),
  ].join(' | ');
  return crypto.createHash('sha256').update(basis).digest('hex');
}

/** Applies the per-source filters declared in sources/registry.yaml. */
function passesFilter(article, filter) {
  if (!filter) return true;
  if (filter.path_contains?.length) {
    const path = (() => {
      try {
        return new URL(article.url).pathname;
      } catch {
        return article.url;
      }
    })();
    if (!filter.path_contains.some(p => path.includes(p))) return false;
  }
  if (filter.keywords?.length) {
    const hay = `${article.title} ${article.summary_raw ?? ''}`.toLowerCase();
    if (!filter.keywords.some(k => hay.includes(k.toLowerCase()))) return false;
  }
  if (filter.author && article.author) {
    if (!article.author.toLowerCase().includes(filter.author.toLowerCase())) return false;
  }
  return true;
}

/**
 * Google News appends " - Publisher" to every headline. The sheet already
 * prints the source beside each item, so the suffix is duplication — and on a
 * long regulator name it pushes the actual headline out of view.
 *
 * Only the last segment is removed, and only when it is short and free of
 * sentence punctuation, so a headline that legitimately contains " - " keeps
 * its own text.
 */
function cleanSyndicatedTitle(title, url) {
  const t = String(title || '').trim();
  if (!/(^|\.)news\.google\.com$/i.test(safeHost(url))) return t;
  // " - Publisher" with nothing before it: Google indexed the page with no
  // headline. Trimming has already moved the dash to position 0, so the split
  // below cannot see it — catch the case explicitly and return nothing.
  if (/^-\s+/.test(t)) return '';
  // Greedy, so a headline containing its own " - " splits at the LAST separator
  // and keeps its text: "SUPA ENERGY - THE BASE network exemption - AER".
  const m = t.match(/^([\s\S]*)\s+-\s+([^-]{2,60})$/);
  if (!m) return t;
  if (/[.!?]$/.test(m[2].trim())) return t;
  // May legitimately come back empty: Google indexes some pages with no
  // headline at all, leaving only " - Publisher". normalise() drops those.
  return m[1].trim();
}

function safeHost(url) {
  try { return new URL(url).hostname; } catch { return ''; }
}

function normalise(raw, source) {
  return raw
    .map(a => ({ ...a, title: cleanSyndicatedTitle(a.title, a.url) }))
    // Title is checked after cleaning, not before. Twenty of thirty-five AER
    // entries arrived as " - Australian Energy Regulator (AER)" — Google had
    // indexed the page with no headline, so once the publisher suffix goes
    // there is nothing left. Storing those means rows whose title is a
    // publisher's name, which is worse than not having the row.
    .filter(a => a.url && a.title && a.title.length >= 8)
    .filter(a => passesFilter(a, source.config?.filter))
    .map(a => ({
      source_id: source.id,
      url: a.url,
      title: a.title.slice(0, 500),
      author: a.author?.slice(0, 200) ?? null,
      published_at: a.published_at,
      summary_raw: a.summary_raw?.slice(0, 4000) ?? null,
      content_hash: contentHash(a),
    }));
}



// --- end shared parser ---

// --- model-backed reader ---
/**
 * Last-resort article extraction, using the Hermes model already on the VPS.
 *
 * Shared by the ingest workflow and the source-repair harness, so it is written
 * to be inlined into an n8n Code node: no require, no backticks, no dollar-brace.
 *
 * Why this exists. Thirty-one of the sixty-eight sources have no feed and are
 * parsed out of HTML, and the site-by-site guesswork in that parser quietly fails.
 * On 22 August the Clean Energy Council page carried 533 article links and the
 * parser returned two — both navigation. NABERS, Commercial Building Disclosure,
 * Victorian Energy Upgrades and DEECA have between zero and one article each,
 * having reported "ok" for months. Writing a bespoke reader per site is a
 * maintenance treadmill; the markup changes and the failure is silent.
 *
 * So when the ordinary parser comes back with nothing useful, the page is handed
 * to the model with the question a person would ask: which of these links are
 * news articles, and what are they called.
 *
 * What this CANNOT do, and must not be asked to: a page we are refused. DCCEEW
 * and the IEA return 403 to both plain HTTP and headless Chromium. No model reads
 * a page it cannot fetch — that needs a different route, not a cleverer parser.
 */

// Hermes 3 8B runs at roughly 7.5 tokens a second on this VPS, so the prompt has
// to be small. Candidates are pre-filtered and capped rather than sending markup.
const MAX_CANDIDATES = 60;
const MIN_TEXT = 18;

/** Anchors that could plausibly be articles, as {url, text}. */
const candidates = (html, baseUrl) => {
  const out = [];
  const seen = new Set();
  // The inner cap has to be generous. A modern card link wraps an image, a
  // category chip and a date in nested divs, and at 200 characters the lazy match
  // simply never reached the closing tag — Clean Energy Council yielded 8 links
  // out of 533, and premier.vic.gov.au yielded none at all from 125 KB.
  const re = /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]{0,4000}?)<\/a>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    let url = m[1];
    const text = m[2].replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ')
      .replace(/\s+/g, ' ').trim();
    if (text.length < MIN_TEXT) continue;
    if (/^(#|mailto:|tel:|javascript:)/i.test(url)) continue;
    // Navigation, legal and social links are never the article.
    if (/\/(tag|category|author|search|login|privacy|terms|contact|about|subscribe)\b/i.test(url)) continue;
    if (/^(home|menu|search|login|sign in|subscribe|read more|learn more|view all|next|previous)$/i.test(text)) continue;
    try { url = new URL(url, baseUrl).toString(); } catch (e) { continue; }
    const key = url.split('#')[0];
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ url: key, text: text.slice(0, 120) });
  }
  return out;
};

/**
 * Ask the model which candidates are real articles.
 *
 * http is the caller's request function — this.helpers.httpRequest inside n8n, or
 * a small wrapper elsewhere — so the module stays free of imports.
 */
const hermesExtract = async (opts) => {
  const html = opts.html || '';
  const baseUrl = opts.baseUrl || '';
  const http = opts.http;
  const model = opts.model || 'hermes3:8b';
  const url = opts.ollamaUrl || 'http://ollama:11434/api/generate';

  const all = candidates(html, baseUrl);
  if (!all.length) return { articles: [], considered: 0, reason: 'no candidate links in the page' };

  // Same-host links first: an index page is mostly its own articles, and the rest
  // is usually syndication and social.
  let host = '';
  try { host = new URL(baseUrl).host; } catch (e) { host = ''; }
  const ranked = all
    .filter(c => !host || c.url.indexOf(host) > -1)
    .slice(0, MAX_CANDIDATES);
  if (!ranked.length) return { articles: [], considered: all.length, reason: 'no same-host links' };

  const listing = ranked.map((c, i) => (i + 1) + '. ' + c.text + '  ->  ' + c.url).join('\n');

  const prompt = 'You are reading the news index of an Australian energy or building industry site.\n'
    + 'Below are the links on the page. Decide which are individual NEWS ARTICLES or MEDIA RELEASES.\n\n'
    + 'Include: news stories, media releases, announcements, articles with a headline.\n'
    + 'Exclude: navigation, section pages, report downloads, event listings, membership or\n'
    + 'contact pages, category indexes, and anything that is a heading rather than a story.\n\n'
    + 'Return ONLY a JSON array, no prose and no markdown fence, of the form\n'
    + '[{"n": <the number from the list>, "title": "<the headline, cleaned up>"}]\n'
    + 'If none of them are articles, return [].\n\n'
    + 'LINKS:\n' + listing + '\n';

  let text = '';
  try {
    const res = await http({
      method: 'POST', url: url, json: true, timeout: 180000,
      body: { model: model, stream: false, options: { temperature: 0.1, num_predict: 900 }, prompt: prompt },
    });
    text = String((res && res.response) || '');
  } catch (e) {
    return { articles: [], considered: ranked.length, reason: 'model unavailable: ' + String(e.message || e).slice(0, 80) };
  }

  // Small models wander outside the fence even when told not to.
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  if (start < 0 || end <= start) {
    return { articles: [], considered: ranked.length, reason: 'model returned no JSON array' };
  }
  let picked;
  try { picked = JSON.parse(text.slice(start, end + 1)); }
  catch (e) { return { articles: [], considered: ranked.length, reason: 'unparseable JSON from model' }; }
  if (!Array.isArray(picked)) return { articles: [], considered: ranked.length, reason: 'model did not return an array' };

  const articles = [];
  const used = new Set();
  for (const p of picked) {
    const n = Number(p && p.n);
    if (!n || n < 1 || n > ranked.length || used.has(n)) continue;
    used.add(n);
    const c = ranked[n - 1];
    const title = String((p && p.title) || c.text).replace(/\s+/g, ' ').trim();
    if (title.length < MIN_TEXT) continue;
    articles.push({ url: c.url, title: title.slice(0, 300) });
  }
  return { articles: articles, considered: ranked.length, reason: '' };
};



// --- end model-backed reader ---

const helpers = this.helpers;

// Mail that is plainly not a newsletter. Cheap to exclude here rather than
// spending forty seconds of model time discovering it.
const NOT_NEWS = /^(re|fwd|out of office|undeliverable|delivery status|password|verify your|confirm your|receipt|invoice|your order)\b/i;

// Tracking wrappers are the norm in newsletters, and the real URL is usually a
// parameter inside them. Storing the wrapper would defeat deduplication, since
// the same article arrives with a different tracking id every time.
const unwrap = (u) => {
  try {
    const parsed = new URL(u);
    for (const key of ['url', 'u', 'target', 'redirect', 'link', 'dest']) {
      const inner = parsed.searchParams.get(key);
      if (inner && /^https?:\/\//i.test(inner)) return inner.split('#')[0];
    }
    // Strip the campaign parameters so two sends of one article agree.
    for (const junk of ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','mc_cid','mc_eid']) {
      parsed.searchParams.delete(junk);
    }
    return parsed.toString().split('#')[0];
  } catch (e) { return u; }
};

const rows = [];
const messages = [];

for (const item of $input.all()) {
  const j = item.json;
  const from = String(j.from || (j.headers && j.headers.from) || '').toLowerCase();
  const subject = String(j.subject || '');
  const messageId = String((j.headers && j.headers['message-id']) || j.messageId || '').trim()
    || (from + '|' + subject + '|' + String(j.date || ''));
  const html = String(j.textHtml || j.html || j.textPlain || j.text || '');

  if (!html || NOT_NEWS.test(subject.trim())) continue;

  // Which source this belongs to is resolved in SQL, by matching the sending
  // address against newsletter_senders. Doing it there rather than here means
  // adding a publisher is one row, not a code change and a redeploy.
  //
  // Every message is read regardless of whether the sender is known. A
  // newsletter subscribed to next month should work immediately, and a publisher
  // quietly changing its sending domain is exactly the failure that goes
  // unnoticed for weeks.
  const domain = (from.match(/@([a-z0-9.-]+)/) || [null, 'mail.invalid'])[1];
  const h = await hermesExtract({
    html, baseUrl: 'https://' + domain, http: helpers.httpRequest,
  });

  const kept = [];
  for (const a of h.articles) {
    const url = unwrap(a.url);
    if (!/^https?:\/\//i.test(url)) continue;
    kept.push({ url: url, title: a.title, from_address: from.slice(0, 200), published_at: j.date || null });
  }

  messages.push({
    message_id: messageId.slice(0, 400),
    from_address: from.slice(0, 200),
    subject: subject.slice(0, 400),
    received_at: j.date || null,
    links_found: h.considered || 0,
    articles_kept: kept.length,
  });
  for (const k of kept) rows.push(k);
}

return [{ json: {
  payload: JSON.stringify(rows),
  messages: JSON.stringify(messages),
  article_count: rows.length,
  message_count: messages.length,
} }];
